package ui

// AdminAuroraCSS defines the "Aurora" admin visual theme mode's chrome
// palette (warm paper + ink-navy, hairline rules, square corners),
// restyling the shared, mode-agnostic sidebar/topbar/
// card/button/input markup the same way AdminNovaCSS, AdminShadcnCSS, and
// AdminWorkbenchCSS do (ADR-0041), reusing the shared semantic token names
// from AdminCSS (ADR-0053). Unlike those three, Aurora's *dashboard body* is
// not restyled here - it is its own Tailwind-authored markup (ADR-0339),
// kept in the separate, prefixed aurora.CSSText stylesheet. This file only
// covers the shell chrome, so the "aurora" family re-skins the whole shell
// the same way every other family does. See
// docs/architecture/0339-tailwind-admin-visual-family.md.
const AdminAuroraCSS = `html[data-ui-theme="aurora"]{--bg:#faf9f6;--surface:#ffffff;--surface-raised:#ffffff;--surface-hover:#eef0ff;--bg-subtle:#f1f1ec;--ink:#111111;--ink-secondary:#43423d;--muted:#86847a;--line:#111111;--line-light:#d8d6cc;--brand:#2b3bf2;--brand-hover:#1c29d6;--brand-light:#2b3bf2;--brand-subtle:#e7e9ff;--brand-glow:rgba(43,59,242,.25);--brand-ink:#ffffff;--green:#16803c;--green-subtle:#e9f7ee;--red:#d6321f;--red-subtle:#fcebe8;--amber:#b5790a;--radius-xs:0px;--radius-sm:3px;--radius-md:3px;--radius-lg:4px;--radius-xl:4px;--shadow-xs:none;--shadow-sm:3px 3px 0 0 #111111;--shadow-md:5px 5px 0 0 #111111;--shadow-lg:7px 7px 0 0 #111111;--card-highlight:3px 3px 0 0 #111111}html[data-ui-theme="aurora"][data-theme="dark"]{--bg:#121212;--surface:#1a1a1a;--surface-raised:#1f1f1f;--surface-hover:#22244a;--bg-subtle:#1a1a1a;--ink:#f5f4ef;--ink-secondary:#c7c5ba;--muted:#8e8c82;--line:#f5f4ef;--line-light:#3a392f;--brand:#7c89ff;--brand-hover:#95a0ff;--brand-light:#7c89ff;--brand-subtle:#1d2150;--brand-glow:rgba(124,137,255,.3);--brand-ink:#0b0d2b;--green:#5fcf87;--green-subtle:#113321;--red:#ff8673;--red-subtle:#3a1511;--amber:#e3ae55;--shadow-xs:none;--shadow-sm:3px 3px 0 0 #f5f4ef;--shadow-md:5px 5px 0 0 #f5f4ef;--shadow-lg:7px 7px 0 0 #f5f4ef;--card-highlight:3px 3px 0 0 #f5f4ef}html[data-ui-theme="aurora"] body{background:var(--bg);color:var(--ink);font-feature-settings:"tnum" 1}html[data-ui-theme="aurora"] .studio-sidebar{background:var(--surface);border-right:2px solid var(--line);box-shadow:none}html[data-ui-theme="aurora"] .sidebar-header{border-bottom:2px solid var(--line);background:var(--brand);color:var(--brand-ink)}html[data-ui-theme="aurora"] .sidebar-bottom{border-top:2px solid var(--line);background:var(--surface)}html[data-ui-theme="aurora"] .studio-brand{color:var(--brand-ink)}html[data-ui-theme="aurora"] .sidebar-section-label{color:var(--muted);text-transform:uppercase;letter-spacing:.09em;font-weight:700}html[data-ui-theme="aurora"] .nav-item{color:var(--ink-secondary);border-radius:0;border:2px solid transparent;font-weight:600}html[data-ui-theme="aurora"] .brand-text small{color:var(--brand-ink);opacity:.75}html[data-ui-theme="aurora"] .brand-logo-mark{background:var(--ink);color:var(--bg);border-radius:0;box-shadow:none}html[data-ui-theme="aurora"] .nav-item:hover{background:var(--brand-subtle);color:var(--brand);border-color:var(--ink)}html[data-ui-theme="aurora"] .nav-item.is-active{background:var(--brand)!important;color:var(--brand-ink)!important;border-color:var(--ink)!important;box-shadow:var(--card-highlight)!important;font-weight:700!important}html[data-ui-theme="aurora"] .studio-topbar{background:var(--surface);border-bottom:2px solid var(--line);box-shadow:none}html[data-ui-theme="aurora"] .studio-card,html[data-ui-theme="aurora"] .dashboard-kpi,html[data-ui-theme="aurora"] .dashboard-card,html[data-ui-theme="aurora"] .collection-tile,html[data-ui-theme="aurora"] .tool-tile,html[data-ui-theme="aurora"] .meta-item,html[data-ui-theme="aurora"] .report-info-card{background:var(--surface);border:2px solid var(--line);box-shadow:var(--card-highlight)}html[data-ui-theme="aurora"] .studio-card,html[data-ui-theme="aurora"] .dashboard-kpi,html[data-ui-theme="aurora"] .dashboard-card,html[data-ui-theme="aurora"] .report-info-card{border-radius:0}html[data-ui-theme="aurora"] .studio-form button:not(.button-quiet):not(.button-secondary),html[data-ui-theme="aurora"] .button:not(.button-quiet):not(.button-secondary),html[data-ui-theme="aurora"] .studio-card button:not(.button-quiet):not(.button-secondary){border-radius:0;border:2px solid var(--ink);background:var(--brand);color:var(--brand-ink);box-shadow:var(--card-highlight);font-weight:700}html[data-ui-theme="aurora"] .studio-form button:not(.button-quiet):not(.button-secondary):hover,html[data-ui-theme="aurora"] .button:not(.button-quiet):not(.button-secondary):hover,html[data-ui-theme="aurora"] .studio-card button:not(.button-quiet):not(.button-secondary):hover{background:var(--brand-hover);color:var(--brand-ink);transform:translate(1px,1px);box-shadow:1px 1px 0 0 var(--ink)}html[data-ui-theme="aurora"] .button-quiet,html[data-ui-theme="aurora"] .button-secondary{border-radius:0;background:var(--surface)!important;color:var(--ink)!important;border:2px solid var(--ink)!important;box-shadow:none;font-weight:700}html[data-ui-theme="aurora"] .button-quiet:hover,html[data-ui-theme="aurora"] .button-secondary:hover{background:var(--bg-subtle)!important;color:var(--brand)!important;border-color:var(--brand)!important}html[data-ui-theme="aurora"] .studio-search{border:2px solid var(--line);border-radius:0;background:var(--surface);box-shadow:none}html[data-ui-theme="aurora"] .studio-search:hover{border-color:var(--brand)}html[data-ui-theme="aurora"] .studio-search:focus-within{border-color:var(--brand);box-shadow:3px 3px 0 0 var(--brand)}html[data-ui-theme="aurora"] .theme-toggle-btn,html[data-ui-theme="aurora"] .studio-user{border:2px solid var(--line);border-radius:0;background:var(--surface);box-shadow:none}html[data-ui-theme="aurora"] input,html[data-ui-theme="aurora"] select,html[data-ui-theme="aurora"] textarea,html[data-ui-theme="aurora"] .studio-form input,html[data-ui-theme="aurora"] .studio-form select,html[data-ui-theme="aurora"] .studio-form textarea,html[data-ui-theme="aurora"] .studio-card input,html[data-ui-theme="aurora"] .studio-card select,html[data-ui-theme="aurora"] .studio-card textarea{border-radius:0;background:var(--surface);border:2px solid var(--line);color:var(--ink)}html[data-ui-theme="aurora"] input:focus,html[data-ui-theme="aurora"] select:focus,html[data-ui-theme="aurora"] textarea:focus,html[data-ui-theme="aurora"] .studio-form input:focus,html[data-ui-theme="aurora"] .studio-form select:focus,html[data-ui-theme="aurora"] .studio-form textarea:focus,html[data-ui-theme="aurora"] .studio-card input:focus,html[data-ui-theme="aurora"] .studio-card select:focus,html[data-ui-theme="aurora"] .studio-card textarea:focus{border-color:var(--brand);box-shadow:3px 3px 0 0 var(--brand)}html[data-ui-theme="aurora"] .studio-heading h1,html[data-ui-theme="aurora"] .dashboard-welcome h2{letter-spacing:-.02em;font-weight:800}html[data-ui-theme="aurora"] .studio-badge-status{border:2px solid var(--ink);background:var(--amber);color:var(--ink);border-radius:0;font-weight:700}html[data-ui-theme="aurora"] ::selection{background:var(--brand);color:var(--brand-ink)}html[data-ui-theme="aurora"] :focus-visible{outline:2px solid var(--brand);outline-offset:2px}`

// AdminAuroraDensityCSS mirrors AdminNovaDensityCSS's layout density rules,
// re-scoped to the Aurora mode's chrome.
const AdminAuroraDensityCSS = `html[data-ui-theme="aurora"] .studio-content{max-width:1600px}html[data-ui-theme="aurora"] .studio-card,html[data-ui-theme="aurora"] .dashboard-card{padding:20px 22px}html[data-ui-theme="aurora"] .studio-card h2,html[data-ui-theme="aurora"] .dashboard-card h2{font-size:1.02rem;letter-spacing:-.01em}html[data-ui-theme="aurora"] .studio-card th{background:var(--bg-subtle);color:var(--muted);font-size:.68rem;letter-spacing:.06em;text-transform:uppercase}html[data-ui-theme="aurora"] .studio-card td{font-size:.8rem}html[data-ui-theme="aurora"] .nav-item{min-height:38px;padding:9px 12px;font-size:.84rem;border-radius:var(--radius-md)}html[data-ui-theme="aurora"] .sidebar-section-label{margin:12px 10px 4px;font-size:.64rem;letter-spacing:.08em}html[data-ui-theme="aurora"] .studio-search{min-height:36px;height:36px;font-size:.84rem;border-radius:var(--radius-md)}html[data-ui-theme="aurora"] .button,html[data-ui-theme="aurora"] .studio-form button{min-height:38px;height:38px;padding:0 18px;font-size:.82rem;font-weight:600;border-radius:var(--radius-md)}html[data-ui-theme="aurora"] .button-quiet,html[data-ui-theme="aurora"] .button-secondary{min-height:38px;height:38px;padding:0 18px;font-size:.82rem;border-radius:var(--radius-md);color:var(--ink)!important}html[data-ui-theme="aurora"] .studio-alert{border:1px solid var(--red);border-radius:var(--radius-md)}html[data-ui-theme="aurora"] .studio-form label{font-size:.76rem;font-weight:600}html[data-ui-theme="aurora"] .studio-form input,html[data-ui-theme="aurora"] .studio-form select,html[data-ui-theme="aurora"] .studio-form textarea{font-size:.82rem;border-radius:var(--radius-md)}`

// AdminAuroraTypeCSS mirrors AdminNovaTypeCSS's font-family rules, re-scoped
// to the Aurora mode's chrome (the Tailwind-authored dashboard body sets its
// own font stack via utility classes, independent of this).
const AdminAuroraTypeCSS = `html[data-ui-theme="aurora"] body,html[data-ui-theme="aurora"] button,html[data-ui-theme="aurora"] input,html[data-ui-theme="aurora"] select,html[data-ui-theme="aurora"] textarea{font-family:"Inter",-apple-system,BlinkMacSystemFont,"Segoe UI Variable","Segoe UI",sans-serif!important;letter-spacing:-.011em}html[data-ui-theme="aurora"] code,html[data-ui-theme="aurora"] kbd,html[data-ui-theme="aurora"] pre{font-family:"JetBrains Mono","IBM Plex Mono","SFMono-Regular",Consolas,monospace!important}`

// AdminAuroraDashboardLayoutCSS toggles which dashboard markup is visible for
// the fifth admin visual family, "aurora" (ADR-0339), following the exact
// client-only display-toggle pattern AdminNovaDashboardLayoutCSS established
// for Nova (ADR-0335): every family's dashboard markup is always rendered
// into the page, and CSS alone decides which one is visible for the active
// html[data-ui-theme] value. Unlike the other four families, Aurora's own
// dashboard body is NOT re-skinned by AdminAuroraCSS above - it is authored
// directly with Tailwind utility classes and its own compiled, namespaced
// stylesheet (aurora.CSSText, concatenated into the shared admin stylesheet
// in admin_shell.go). See docs/architecture/0339-tailwind-admin-visual-family.md.
const AdminAuroraDashboardLayoutCSS = `html:not([data-ui-theme="aurora"]) .aurora-dashboard{display:none}
html[data-ui-theme="aurora"] .wb-dashboard{display:none}
html[data-ui-theme="aurora"] .nova-dashboard{display:none}`
